const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Define northeastern Pacific Ocean region
  const region = ee.Geometry.Polygon([
    [[-180, 20], [-120, 20], [-120, 60], [-180, 60], [-180, 20]]
  ]);

  // 2. Data Acquisition - NOAA OISST dataset
  const sstCollection = ee.ImageCollection('NOAA/CDR/OISST/V2_1')
    .select('sst');

  // Get August 2019 data
  const aug2019 = sstCollection
    .filterDate('2019-08-01', '2019-08-31')
    .filterBounds(region);

  // Get baseline data (1985-2012 August averages)
  const baseline = sstCollection
    .filter(ee.Filter.calendarRange(1985, 2012, 'year'))
    .filter(ee.Filter.calendarRange(8, 8, 'month'))
    .filterBounds(region);

  // Check collection sizes
  const aug2019Size = aug2019.size().getInfo();
  const baselineSize = baseline.size().getInfo();

  console.log(`August 2019 images: ${aug2019Size}`);
  console.log(`Baseline (1985-2012) August images: ${baselineSize}`);

  if (aug2019Size === 0 || baselineSize === 0) {
    console.log("<answer>C1</answer>");
    return;
  }

  // 3. Processing - Calculate means
  const aug2019Mean = aug2019.mean();
  const baselineMean = baseline.mean();

  // Get pixel counts to check for valid data
  const aug2019Count = aug2019Mean.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: region,
    scale: 25000,
    maxPixels: 1e9
  }).get('sst').getInfo();

  const baselineCount = baselineMean.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: region,
    scale: 25000,
    maxPixels: 1e9
  }).get('sst').getInfo();

  console.log(`August 2019 valid pixels: ${aug2019Count}`);
  console.log(`Baseline valid pixels: ${baselineCount}`);

  if (aug2019Count === 0 || baselineCount === 0) {
    console.log("<answer>C2</answer>");
    return;
  }

  // 4. Calculate mean temperatures
  const aug2019Temp = aug2019Mean.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: region,
    scale: 25000,
    maxPixels: 1e9
  }).get('sst').getInfo();

  const baselineTemp = baselineMean.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: region,
    scale: 25000,
    maxPixels: 1e9
  }).get('sst').getInfo();

  console.log(`August 2019 mean SST: ${aug2019Temp?.toFixed(2)}°C`);
  console.log(`Baseline mean SST: ${baselineTemp?.toFixed(2)}°C`);
  console.log(`Difference: ${(aug2019Temp - baselineTemp)?.toFixed(2)}°C`);

  // 5. Validation & Final Answer
  if (aug2019Temp === null || baselineTemp === null || 
      isNaN(aug2019Temp) || isNaN(baselineTemp) ||
      aug2019Temp > 50 || baselineTemp > 50 || // Unrealistic SST values
      aug2019Temp < -5 || baselineTemp < -5) {
    console.log("<answer>C3</answer>");
  } else if (aug2019Temp < baselineTemp) {
    console.log("<answer>A</answer>");
  } else {
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
